import os,re,json,numpy as np
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
i1,o1=G['Demo pair 1 input'],G['Demo pair 1 output']
i2,o2=G['Demo pair 2 input'],G['Demo pair 2 output']
# rule: fill the blank row between two blocks with color 3
def f(a):
    b=np.array(a); rows=[i for i,r in enumerate(b) if any(v for v in r)]
    out=b.copy()
    gaps=[(rows[i]+1, rows[i+1]-1) for i in range(len(rows)-1) if rows[i+1]-rows[i]-1>=1]
    for top,bot in gaps:
        out[top:bot+1, :] = 3
    return out.tolist()
print(f(i1)==o1, f(i2)==o2)
out=f(G['Test input'])
for r in out: print(r)
